INSERT INTO GRU.GRU_REJECT_TAB ( ID, SYSTEMACCOUNT, VISTA_TAB_ID, UTERRARIO, OLDTBAL, NEWTBAL, FRONT_TIMESTAMP, FRONT_STATUS, REJECT_DESC, CHECK_STATUS, CHECK_TIMESTAMP ) SELECT GRU.GRU_REJECT_TAB_SEQ.NEXTVAL, t.* FROM (
SELECT #{item.systemAccount} AS SYSTEMACCOUNT, #{item.vistaTabId} AS VISTA_TAB_ID, #{item.uterrario} AS UTERRARIO, #{item.oldTbal} AS OLDTBAL, #{item.newTbal} AS NEWTBAL, SYSDATE AS FRONT_TIMESTAMP, #{item.frontStatus} AS FRONT_STATUS, #{item.rejectDesc} AS REJECT_DESC, #{item.checkStatus} AS CHECK_STATUS, SYSDATE AS CHECK_TIMESTAMP FROM DUAL
) t
